INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(5, 'koKR', 'Burczący brzuch Dygota', 'Od tygodni ukrywam się w tym wymarłym miasteczku i nie jadłem nic poza larwami i chwastami! Potrzebuję porządnego jedzenia i chętnie dobrze za nie zapłacę.$B$BPrzynieś mi prawdziwą ucztę, a sowicie cię wynagrodzę.$B$BSłyszałem, że kucharz Grual z tawerny „Szkarłatny Kruk” w Mrocznych Włościach robi przepyszne zmierzchowe kotleciki krabowe...', 'Porozmawiaj z kucharzem Grualem.', '', '', '', '', '', '', 0),
(55, 'koKR', 'Morbent Fel', 'Morbent Fel kryje się w swoim leżu – w domu przycupniętym na szczycie wzgórza na wschodzie, ponad cmentarzem na Kruczym Wzgórzu. Jego czas na tej ziemi dobiega końca...$B$BUżyj przeciw niemu Zguby Morbenta. Odbierze ona moc jego ochronnym czarom.$B$BZabij go. Zabij go i uwolnij nas od jego nikczemności. Bądź narzędziem mojej zemsty i $gbohaterem:bohaterką; Kniei Zmierzchu!', 'Użyj Zguby Morbenta na Morbencie Felu, zabij go, a potem zwróć Zgubę Morbenta Svenowi w jego obozie.', '', 'Wróć do Svena Yorgena na Cichym Brzegu w Kniei Zmierzchu.', 'Morbent Fel zabity', '', '', '', 0),
(56, 'koKR', 'Nocna Straż', 'Jako dowódca Nocnej Straży przysięgłam chronić mieszkańców Mrocznych Włości. Wichrogród odwołał stąd swoich strażników i zostawił nas samym sobie.$b$bJeśli czujesz, że $gjesteś godzien:jesteś godna; tego zadania, potrzebujemy twojej pomocy! Wesprzyj Nocną Straż: wyrusz na Cmentarz Spokojnych Ogrodów, tuż na południe od Mrocznych Włości, i zabij 8 szkieletowych wojowników oraz 6 szkieletowych magów. Trzeba powstrzymać zagrożenie ze strony nieumarłych!', 'Dowódca Althea Ebonlocke z Mrocznych Włości chce, żebyś $gzabił:zabiła; 8 szkieletowych wojowników i 6 szkieletowych magów.', '', 'Wróć do dowódcy Althei Ebonlocke w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(57, 'koKR', 'Nocna Straż', '$N, docierają do mnie meldunki, że las roi się od nieumarłych! Jeśli podołasz zadaniu, udaj się na cmentarz na Kruczym Wzgórzu i zabij 15 tych plugawych szkieletowych biesów oraz 15 szkieletowych poczwar. Donoszą też o szkieletach tuż na południe od Mrocznych Włości, na Cmentarzu Spokojnych Ogrodów i w jego okolicy. Trzeba wypędzić nieumarłych z Kniei Zmierzchu!', 'Dowódca Althea Ebonlocke z Mrocznych Włości chce, żebyś $gzabił:zabiła; 15 szkieletowych biesów i 15 szkieletowych poczwar.', '', 'Wróć do dowódcy Althei Ebonlocke w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(58, 'koKR', 'Nocna Straż', 'Sytuacja na Kruczym Wzgórzu wciąż jest ponura. Bezpieczeństwo Mrocznych Włości jest w twoich rękach, $N. Nie mam dość wartowników, by ochronić miasto. Musisz raz jeszcze wyruszyć na Krucze Wzgórze i oczyścić wschodnie mauzoleum z 20 roznosicieli zarazy!', 'Dowódca Althea Ebonlocke z Mrocznych Włości chce, żebyś $gzabił:zabiła; 20 roznosicieli zarazy we wschodnim mauzoleum na Kruczym Wzgórzu.', '', 'Wróć do dowódcy Althei Ebonlocke w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(66, 'koKR', '', 'Zeszłej nocy przez moje żyły przetoczył się straszliwy niepokój. Wyczułam, że moja wnuczka, Alyssa, jest w wielkim niebezpieczeństwie. Zapytałam karty i ze stołu spojrzała na mnie Śmierć.$b$bPo długiej wędrówce w mrocznym transie zdołałam odnaleźć trop tej przerażającej tajemnicy. Przyszło do mnie imię. Imię Stalvana.$b$bOdszukaj urzędnika w Ratuszu i spróbuj dowiedzieć się czegoś więcej o tej postaci. Lękam się o nas wszystkich.', 'Odszukaj urzędnika Daltry\'ego w Ratuszu w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(79, 'koKR', '', 'Przez lata śledziłem legendę tego całego Stalvana. Kiedy kilka lat temu wyrżnięto przyjezdnych szlachciców, poszedłem z Haggardem zbadać sprawę. Znalazłem te zabłocone kartki, ale nigdy nie zdołaliśmy dopasować pisma do tego szaleńca z lasu. Zebrane przez ciebie dowody potwierdzają jego winę. Zanieś to natychmiast dowódcy Ebonlocke i opowiedz jej, czego się $gdowiedziałeś:dowiedziałaś;!', 'Zanieś zabłoconą kartkę dowódcy Ebonlocke.', '', '', '', '', '', '', 0),
(80, 'koKR', '', 'Od dłuższego czasu mam na oku tego odrażającego typa, Stalvana. Ale jeśli tę kartkę napisała ta sama ręka, dowodzi to jego winy ponad wszelką wątpliwość.$b$bPrzez lata prowadzenia miejskiego rejestru urzędnik Daltry stał się znawcą charakterów pisma. Pokaż mu tę kartkę i sprawdź, czy pismo zgadza się z podpisem w rejestrze.', 'Pokaż urzędnikowi Daltry\'emu zakrwawioną kartkę z dziennika.', '', '', '', '', '', '', 0),
(90, 'koKR', 'Przyprawione szaszłyki z wilka', 'Przyprawione szaszłyki z wilka to ulubiony przysmak naszych gości! Jasne, mogę ci ich trochę zrobić. Ale najpierw potrzebuję składników. Przynieś mi 10 chudych wilczych udźców i trochę wichrogrodzkich ziół przyprawowych. W tym lesie jest tyle wilków, że na pewno bez trudu zdobędziesz udźce. Po zioła zgłoś się do Felicii Gump, która prowadzi kwiaciarnię w dzielnicy kanałów w Wichrogrodzie.', 'Zbierz 10 chudych wilczych udźców i wichrogrodzkie zioła przyprawowe, a potem wróć do kucharza Gruala w Mrocznych Włościach.', '', 'Wróć do kucharza Gruala w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(93, 'koKR', 'Zmierzchowe kotleciki krabowe', 'Zdradzę ci mały sekret – zmierzchowe kotleciki „krabowe” tak naprawdę robi się z pajęczych nóg! Wiem, że to trochę obrzydliwe, ale mają przyjemny, pikantny smak i są świetną przekąską! Przynieś mi ciągnące się pajęcze nogi, a upichcę ci kilka.$B$BPodobno jadosieciowe pająki to dobre źródło – gnieżdżą się na północy, między podnóżem wzgórz a rzeką.', 'Zbierz 6 ciągnących się pajęczych nóg i zanieś je kucharzowi Grualowi w Mrocznych Włościach.', '', 'Wróć do kucharza Gruala w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(95, 'koKR', 'Zemsta Svena', 'Kiedyś uprawiałem jedną z farm na południowym wschodzie... dopóki Mroczni Jeźdźcy z Przełęczy Wichrowej Zguby nie spadli na moją farmę i nie wyrżnęli mojej rodziny pod moją nieobecność!$B$BGdy wróciłem, zobaczyłem mroczną postać, która skradała się przy mojej stodole i coś zakopywała. Uciekła, zanim zdążyłem ją złapać, a ja nie mogłem zwlekać, bo deptałem Mrocznym Jeźdźcom po piętach. Nigdy więc nie odkryłem, co ukryto.$B$BJeśli znajdziesz to, co zakopała ta mroczna postać, będę ci wdzięczny. Kryjówka jest za starym pniakiem obok mojej stodoły.', 'Udaj się na farmę Svena i znajdź to, co zakopano za starym pniakiem.', '', '', '', '', '', '', 0),
(97, 'koKR', '', 'Natychmiast powiadom dowódcę Ebonlocke, że pismo się zgadza, $N! Jej podejrzenia były słuszne!', 'Przekaż wieści dowódcy Ebonlocke.', '', '', '', '', '', '', 0),
(98, 'koKR', '', 'Stalvan Mgłopłaszcz wiódł zdeprawowane życie. Z jego ręki ginęli niewinni. Bez wątpienia ma na sumieniu niezliczone zbrodnie. Teraz ten szaleniec zagraża Mrocznym Włościom. Tylko Światło wie, jakie plugawe czyny knuje. Udaj się do jego chaty tuż na północ od miasta, $N, i raz na zawsze wykonaj na nim wyrok.$b$bGdy to zrobisz, idź do Madame Evy i pokaż jej jego rodowy pierścień. W końcu to jej przeczucie doprowadziło do tego makabrycznego odkrycia. To dzięki niej Mroczne Włości są bezpieczniejsze.', 'Zabij Stalvana Mgłopłaszcza i pokaż Madame Evie jego rodowy pierścień.', '', 'Wróć do Madame Evy w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(101, 'koKR', 'Totem udręki', 'Gdy mistyczne skażenie pełznie przez las, nie sposób zaprzeczyć, że trzeba się chronić, $N. Wiatry szepczą mi o wielkim niebezpieczeństwie, które cierpliwie czeka na ciebie w niedalekiej przyszłości.$b$bJeśli chcesz się ochronić, przynieś mi 10 kłów ghuli, 10 palców szkieletów i 5 fiolek pajęczego jadu. Zaklnę dla ciebie Totem udręki, który zrani każdego, kto spróbuje użyć wobec ciebie przemocy.', 'Przynieś 10 kłów ghuli, 10 palców szkieletów i 5 fiolek pajęczego jadu Madame Evie w Mrocznych Włościach.', '', 'Wróć do Madame Evy w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(133, 'koKR', 'Straszydło na ghule', 'Mieszkam tak daleko od miejskiej ochrony, że to cud, iż ghule i chodzące trupy jeszcze mnie nie zjadły! Ledwie wczoraj stado przeżuwaczy kości dobijało się do ścian mojego domu!$B$BChcę zrobić kukłę – taki „strach na wróble”, tylko na ghule. Do tego potrzebuję żeber ghuli. Zdobędziesz je od pożeraczy ciał, przeżuwaczy kości, pożeraczy mózgów, zgnilców i roznosicieli zarazy.$B$BPrzynieś mi te żebra, a odpłacę ci się paroma monetami.', 'Zbierz 7 żeber ghuli i zanieś je Abercrombiemu do jego chaty.', '', 'Wróć do Abercrombiego przy Cmentarzu na Kruczym Wzgórzu w Kniei Zmierzchu.', '', '', '', '', 0),
(134, 'koKR', 'Ogrzy złodzieje', 'Kilka tygodni temu zbierałem zioła daleko od domu i napadła na mnie banda ogrów! Uciekłem, ale musiałem zostawić skrzynię cennych narzędzi i ziół.$B$BKiedy już mnie przegoniły, ogry wróciły napuszonym krokiem do ogrzego kopca na południu Kniei Zmierzchu. Jestem pewien, że moja skrzynia leży gdzieś w pobliżu kopca.$B$BProszę, $N, odzyskaj ją dla mnie, bo bardzo mi jej brakuje.', 'Zwróć Abercrombiemu jego skrzynię.', '', 'Wróć do Abercrombiego przy Cmentarzu na Kruczym Wzgórzu w Kniei Zmierzchu.', '', '', '', '', 0),
(148, 'koKR', 'Zapasy z Mrocznych Włości', 'Och, cóż ma począć biedny starzec? Potrzebuję zapasów z Mrocznych Włości, ale wioska jest tak daleko, a ja jestem taki stary i słaby... Nigdy bym tam nie dotarł.$B$BMożesz pójść do Mrocznych Włości i przynieść mi nić z włosów ducha? Dostaniesz ją od Madame Evy w jej domu przy rynku w Mrocznych Włościach.', 'Porozmawiaj z Madame Evą.', '', '', '', '', '', '', 0),
(149, 'koKR', 'Nić z włosów ducha', 'Jest pewien biedny, smutny duch, Ślepa Mary, który nawiedza stary dom na farmie wśród wzgórz na południe od Mrocznych Włości.$B$BWeź ten Widmowy grzebień i poproś Ślepą Mary, żeby uczesała nim włosy. Potem przynieś mi grzebień, a wydobędę z niego włosy ducha, których potrzebuję do nici.$B$BI uważaj, bo w pobliżu tego domu czają się teraz mroczne istoty...', 'Zanieś Widmowy grzebień Ślepej Mary.', '', '', '', '', '', '', 0),
(154, 'koKR', 'Zwróć grzebień', 'NIE!!!!!$B$BZabierz go, zabierz ode mnie ten grzebień!$B$BJestem potworem i nikt już nigdy nie uzna mnie za śliczną!', 'Zanieś Grzebień z włosów ducha Madame Evie w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(156, 'koKR', 'Zbierz kwiaty zgnilizny', 'Jeśli przyniesiesz mi trochę kwiatów zgnilizny, uwarzę ci porcję soku zombie.$B$BKwiaty zgnilizny rosną w dziwnych miejscach. Podobno można je znaleźć w czaszkach szkieletowych poczwar i szkieletowych biesów... choć sam nigdy nie podszedłem na tyle blisko, żeby to sprawdzić!$B$BCmentarz na Kruczym Wzgórzu aż się roi od tych szkieletów. Skoro i tak będziesz tam szukać kwiatów zgnilizny, możesz się ich przy okazji pozbyć. Mieszkańcy Mrocznych Włości będą ci wdzięczni.', 'Zbierz 8 kwiatów zgnilizny i zanieś je szynkarzowi Smittsowi w Mrocznych Włościach.', '', 'Wróć do szynkarza Smittsa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(157, 'koKR', 'Dostarcz nić', 'Oto twoja nić, $N. Ma tysiąc zastosowań – od pętania złych duchów po wszywanie życia w martwe przedmioty.', 'Zanieś nić z włosów ducha Abercrombiemu do jego chaty na północ od Cmentarza na Kruczym Wzgórzu.', '', '', '', '', '', '', 0),
(158, 'koKR', 'Sok zombie', 'Potrzebuję butelki pewnego trunku – soku zombie. Szynkarz Smitts z tawerny „Szkarłatny Kruk” w Mrocznych Włościach powinien go mieć.$B$BI proszę, pospiesz się, $N. Noce robią się zimne, a ja potrzebuję tego trunku, żeby znów rozpalić ogień w żyłach!', 'Porozmawiaj z szynkarzem Smittsem.', '', '', '', '', '', '', 0),
(159, 'koKR', 'Dostawa soku', 'Oto twój sok zombie...$B$B...i uważaj z nim. Jest tak mocny, że postawiłby na nogi umarłego!', 'Zanieś sok zombie Abercrombiemu do jego chaty.', '', '', '', '', '', '', 0),
(160, 'koKR', 'Liścik do burmistrza', 'Zanieś ten liścik Ello Ebonlocke\'owi, burmistrzowi Mrocznych Włości.$B$BJesteśmy starymi przyjaciółmi... a kiedy go przeczyta i dowie się, co dla mnie $gzrobiłeś:zrobiłaś;... na pewno ucieszy się tak samo jak ja! Hahahaha!', 'Zanieś list Abercrombiego Ello Ebonlocke\'owi, burmistrzowi Mrocznych Włości.', '', '', '', '', '', '', 0),
(163, 'koKR', 'Krucze Wzgórze', 'Na Kruczym Wzgórzu dzieje się coś złego, $n. Calor przysięga, że ktoś – albo coś – nawiedza tamtejsze budynki. Dwie noce z rzędu widział, jak poruszają się cienie, a noc wcześniej, jak mówi, dostrzegł światło w jednym z okien.$b$bSkoro, jak mówisz, zależy ci na bezpieczeństwie Kniei Zmierzchu, dowiedz się, jaki potwór nawiedza Krucze Wzgórze.', 'Dowiedz się, co nawiedza Krucze Wzgórze.', '', '', '', '', '', '', 0),
(164, 'koKR', 'Dostawa dla Svena', 'Znasz Svena? To dopiero człowiek, który pełni dzieło Światła! On i jego towarzysze mają obóz na północno-zachodnim skraju Kniei Zmierzchu.$b$bNiestety jest ich tak niewielu, że nie mogą nawet posłać nikogo do miasta po zapasy. Zaniesiesz mu te zapasy?', 'Dostarcz zapasy Svenowi.', '', '', '', '', '', '', 0),
(165, 'koKR', 'Pustelnik', 'Był taki starzec, który dość często przychodził do miasta po zapasy, ale od dłuższego czasu go nie widziałam. Jeśli dobrze pamiętam, mieszka w chacie z widokiem na cmentarz na Kruczym Wzgórzu. Może warto sprawdzić, czy nic mu się nie stało.', 'Zajrzyj do starca w chacie przy cmentarzu na Kruczym Wzgórzu.', '', '', '', '', '', '', 0),
(173, 'koKR', 'Worgeny w lesie', 'Ciemność zdaje się nieubłaganie ciągnąć do Kniei Zmierzchu. Misją mistrza Carevina jest wypędzenie zła i herezji. To dzięki naszym wysiłkom mieszkańcy Mrocznych Włości są bezpieczni.$b$bUważasz, że $gjesteś godzien:jesteś godna;, by do nas dołączyć?$b$bKiedyś myślałem tak jak ty. Rozczarowany gnuśnością Straży, przyłączyłem się do mistrza Carevina. Jeśli chcesz się wykazać, nie zrobisz tego słowami.$b$bSprawdź swoje umiejętności w walce z worgenami – tkaczami cieni z Pożeraczy Nocy w Gaju Jasnego Lasu – jasnego, ha! – i w Gnijącym Sadzie.', 'Zabij 6 worgenów – tkaczy cieni z Pożeraczy Nocy – dla Calora w Mrocznych Włościach.', '', 'Wróć do Calora w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(174, 'koKR', 'Spójrz w gwiazdy', 'Mój gnomi przyjaciel, Cog, obiecał pomóc mi zbudować urządzenie, dzięki któremu będę mógł spoglądać w gwiazdy. Istnieje prawda, poza magią, która może wyjaśnić dziwną przemianę w lesie.$b$bPrzynieś mi brązową rurę wykonaną przez biegłego inżyniera. Według planów Coga to pierwszy krok.', 'Viktori Prism\'Antras z Mrocznych Włości chce, żebyś $gprzyniósł:przyniosła; mu brązową rurę.', '', 'Wróć do Viktoriego Prism\'Antrasa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(175, 'koKR', 'Spójrz w gwiazdy', 'Według planów Coga potrzebuję teraz czegoś, co odbija światło. Pamiętam kobietę imieniem Mary, która słynęła w tych stronach z tego, że zawsze nosiła przy sobie lusterko. Może zdołasz odnaleźć Mary i sprawdzić, czy użyczyłaby nam do tego projektu czegoś, co odbija światło? Zdaje się, że kiedyś mieszkała na południu Kniei Zmierzchu...', 'Odnajdź Mary i przekonaj ją, by oddała coś, co odbija światło, na potrzeby projektu Viktoriego.', '', '', '', '', '', '', 0),
(177, 'koKR', 'Spójrz w gwiazdy', 'Lusterko było jednym z moich największych skarbów aż do... tamtego zdarzenia. Potem wyrzuciłam je za stodołę. Kręcił się tam kiedyś pewien obłąkany ghul. Może je podniósł. Podobno ta diabelska bestia przebywa na Cmentarzu Spokojnych Ogrodów.', 'Odbierz Lusterko Mary obłąkanemu ghulowi i oddaj je Viktoriemu w Mrocznych Włościach.', '', 'Wróć do Viktoriego Prism\'Antrasa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(181, 'koKR', 'Spójrz w gwiazdy', 'Do ukończenia urządzenia brakuje już tylko jednego elementu. Plany Coga wymagają jakiejś soczewki. Jedyna znana mi soczewka, która byłaby dość duża, będzie bardzo trudna do zdobycia.$b$bW kopcu na południu Kniei Zmierzchu mieszka ogr imieniem Zzarc\'Vul. Jeśli zdołasz, przynieś mi jego monokl, a użyję go jako soczewki!', 'Odnajdź Zzarc\'Vula w ogrzym kopcu na południu Kniei Zmierzchu i zanieś jego monokl Viktoriemu w Mrocznych Włościach.', '', 'Wróć do Viktoriego Prism\'Antrasa w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(221, 'koKR', 'Worgeny w lesie', 'Może $gzauważyłeś:zauważyłaś; w lesie większe worgeny, które krążą razem z tkaczami cieni? Z tego, co wiemy, to właśnie mroczni biegacze stanowią większość worgenów.$b$bPodczas swoich wypraw zauważyłem też, że opanowali Gnijący Sad na południowy zachód od miasta. Te worgeny są nieco twardsze od tych, z którymi $gwalczyłeś:walczyłaś; ostatnio.$b$bMiej się na baczności.', 'Zabij 12 worgenów – mrocznych biegaczy z Pożeraczy Nocy – dla Calora w Mrocznych Włościach.', '', 'Wróć do Calora w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(222, 'koKR', 'Worgeny w lesie', 'Twoje dotychczasowe dokonania przekonały mnie, że $gjesteś gotów:jesteś gotowa; zmierzyć się z najgroźniejszymi worgenami, które zalęgły się w lesie.$b$bSpośród worgenów, które się tu zadomowiły, najniebezpieczniejsze okazały się plugawe kły i skażeni. Osiedlili się przy kilku jaskiniach i w kopalni na południu.$b$bZ daleka widać nawet blask ich ognisk...', 'Zabij 8 worgenów – plugawych kłów z Pożeraczy Nocy – i 8 worgenów – skażonych z Pożeraczy Nocy – dla Calora w Mrocznych Włościach.', '', 'Wróć do Calora w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(223, 'koKR', 'Worgeny w lesie', 'Proszę, $n. Zanieś tę wiadomość mistrzowi Carevinowi.$b$b<Szybko wyjmuje kawałek wyblakłego pergaminu i podaje ci go.>$b$bJeszcze kilku takich jak ty, a będzie nas więcej niż Nocnej Straży! Może wtedy zdołalibyśmy dokończyć dzieło, które dziś prowadzi tylko nasza garstka.', 'Zanieś liścik Calora Jonathanowi Carevinowi.', '', '', '', '', '', '', 0),
(225, 'koKR', 'Zniszczony grób', 'Na zniszczonym nagrobku widnieje tylko:$b$bMORGAN LADIMORE$b$b<Przyglądając się uważniej, zauważasz, że ziemię na grobie ktoś niedawno ruszał i że sporej jej części brakuje...>', 'Porozmawiaj z Sirrą Von\'Indi w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(226, 'koKR', 'Wilki na karku', 'Sven i ja mamy przed sobą niebezpieczne dni, zwłaszcza z tym nekromantą na wschodzie. A skoro jesteśmy tu sami, musimy sami polować na jedzenie. Za każdym razem, gdy wracam do obozu z mięsem, z lasu wyłażą wygłodniałe albo wściekłe srogie wilki i chcą coś uszczknąć. Nie trzeba mówić, że życie tutaj to niebezpieczna robota!$B$BAle jeśli pozbędziesz się części tych wilków, będzie nam łatwiej. Grasują głównie na północ i na wschód stąd, przy rzece.', 'Zabij 12 wygłodniałych srogich wilków i 8 wściekłych srogich wilków, a potem wróć do Larsa w obozie Svena na zachodniej granicy Kniei Zmierzchu.', '', 'Wróć do Larsa na Cichym Brzegu w Kniei Zmierzchu.', '', '', '', '', 0),
(227, 'koKR', 'Morgan Ladimore', '<Przeszukuje półki i wyciąga książkę oprawioną w skórę.>$b$bJeśli chcesz wiedzieć więcej, zapytaj Altheę. To ona ostatnio zajmuje się... kłopotami... z nim.', 'Porozmawiaj z dowódcą Altheą Ebonlocke w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(228, 'koKR', 'Mor\'Ladim', 'Według moich zwiadowców Mor\'Ladim krąży po Kniei Zmierzchu, wędrując dziwną, krętą ścieżką przez cmentarz. Pochowaliśmy go za domem na wzgórzu – wiesz, gdzie to jest?$b$bNiczym nie mogę ci pomóc, ale życzę ci powodzenia.', 'Zabij Mor\'Ladima, a potem zanieś jego czaszkę dowódcy Althei Ebonlocke w Mrocznych Włościach.', '', 'Wróć do dowódcy Althei Ebonlocke w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(229, 'koKR', 'Córka, która przeżyła', 'Powinnam była powiedzieć ci o tym wcześniej...$b$bJak by to ująć...$b$bMorgan mógł wierzyć, że cała jego rodzina nie żyje, ale w rzeczywistości jego córka, Sarah Ladimore, jest teraz wartowniczką. Zawsze dręczyły ją... okoliczności... śmierci ojca. Może zaniesiesz jej tę wieść.', 'Porozmawiaj z wartowniczką Sarah Ladimore w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(230, 'koKR', 'Obóz Svena', 'Przekopując kopczyk, znajdujesz małą, poplamioną ziemią książkę.$B$BKsiążka nie ma tytułu, ale... zawiera informacje, które Sven chciałby poznać.', 'Zanieś Svenowi książkę znalezioną na jego farmie.', '', '', '', '', '', '', 0),
(231, 'koKR', 'Miłość córki', 'Weź to i połóż na jego grobie. Może... jakoś się dowie, że nic mi nie jest i że nikt z nas nie wini go za to, co się stało.$b$b<Ma teraz łzy w oczach. Zsuwa pierścień z prawej dłoni i wciska ci go w ręce.>$b$bI... dziękuję ci, $n.', 'Zanieś Pierścień Sarah na grób Morgana Ladimore\'a.', '', '', '', '', '', '', 0),
(240, 'koKR', 'Powrót do Dygota', 'No i proszę – kotleciki „krabowe” à la Grual!', 'Wróć do Dygota ze zmierzchowymi kotlecikami krabowymi.', '', '', '', '', '', '', 0),
(245, 'koKR', 'Ośmionożna plaga', 'Witaj, $N. Może $gwidziałeś:widziałaś; pająki, które opanowały zachodnią granicę? Te ośmionożne paskudy są dla nas za silne, a pani dowódca nie ma dość ludzi, by posłać ich tak daleko od Mrocznych Włości.$b$bNiechętnie cię o to proszę, ale wyglądasz na kogoś, kto sobie z nimi poradzi. Nie mogę obiecać niczego szczególnie cennego, ale nagrodzę cię, jeśli pomożesz wytępić te plugawe robale.$b$bI jeszcze jedna rada: jeśli tylko możesz, unikaj ich jadu.', 'Zabij 15 karłowatych jadosieciowych pająków, a potem zamelduj się u wartownika Doddsa w Kniei Zmierzchu.', '', 'Wróć do wartownika Doddsa w Kniei Zmierzchu.', '', '', '', '', 0),
(251, 'koKR', 'Przetłumacz liścik Abercrombiego', 'Zanieś liścik, który mi $gdałeś:dałaś;, do Sirry Von\'Indi. Zna się na językach i dawnych sztukach – jeśli ktokolwiek tutaj potrafi przetłumaczyć tę wiadomość, to właśnie on.', 'Zanieś List do Ello do Sirry Von\'Indi.', '', '', '', '', '', '', 0),
(252, 'koKR', 'Tłumaczenie dla Ello', 'Ojej! Jeśli to, co tu napisano, jest prawdą, to Abercrombie zrobił coś... niewypowiedzianie strasznego.$B$BLepiej zanieś przetłumaczony liścik z powrotem do Ello.$B$BI to szybko, bo obawiam się, że ku naszemu miastu już zmierza ciężkim krokiem zguba...', 'Zanieś Przetłumaczony list lordowi Ello Ebonlocke\'owi.', '', '', '', '', '', '', 0),
(253, 'koKR', 'Oblubienica Balsamisty', 'Balsamista to postać z jednej z naszych opowieści dla dzieci. Był dobrodusznym alchemikiem, którego śmierć żony, Elizy, doprowadziła do szaleństwa. Aby przywrócić ją do życia, sięgnął po mroczną magię i umieścił własne serce w piersi zmarłej małżonki.$B$BTo ożywiło Elizę... ale przeklęło ją głodem ludzkiego mięsa, więc Balsamista musiał trzymać ją pod ziemią.$B$BJego serce jest źródłem jego mocy. Odnajdź grób jego żony, wydobądź serce i przynieś mi je, póki jeszcze bije. Zrób to, a jego moc zostanie złamana.', 'Znajdź grób Elizy. Odbierz jej Serce Balsamisty, a potem wróć do Ello Ebonlocke\'a.', '', 'Wróć do lorda Ello Ebonlocke\'a w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(254, 'koKR', 'Grzebanie w ziemi', '', '', '', '', '', '', '', '', 0),
(262, 'koKR', 'Mroczna postać', 'Muszę się dowiedzieć, kim był ten, kto czaił się w cieniu tej nocy, gdy zabito moją rodzinę!$B$BProszę, $N, $gdowiodłeś:dowiodłaś; już swojej zaradności. Odnajdź tę mroczną postać. Muszę poznać sekrety, które skrywa!$B$BNie mam żadnych wskazówek, których byś już nie $gznał:znała;, ale proszę – weź książkę, którą $gznalazłeś:znalazłaś; na mojej farmie. Może ktoś z mieszkańców miasta powiąże ją z jej właścicielem.', 'Weź książkę znalezioną na farmie Svena i pokaż ją mieszkańcom Mrocznych Włości.', '', '', '', '', '', '', 0),
(265, 'koKR', 'Dalsze poszukiwania mrocznej postaci', 'Oto twoja książka, $N. Życzę ci szczęścia w poszukiwaniach. Jeśli popytasz innych w mieście, może podsuną ci więcej wskazówek.$B$BA oto jeszcze jedna ode mnie – choć autor tej książki jest w Mrocznych Włościach obcy, samą książkę kupiono tutaj.', 'Sprawdź, czy inni mieszkańcy mają jakieś wskazówki co do mrocznej postaci.', '', '', '', '', '', '', 0),
(266, 'koKR', 'Popytaj w karczmie', 'Oto twoja książka. Powodzenia w poszukiwaniach.$B$BMożesz rozszerzyć je na karczmę. Jeśli osoba, której szukasz, spędziła trochę czasu w mieście, pewnie ktoś ją tam widział.', 'Poszukaj w karczmie wskazówek dotyczących mrocznej postaci.', '', '', '', '', '', '', 0),
(268, 'koKR', 'Powrót do Svena', 'Książka, którą $gznalazłeś:znalazłaś;, była skończona tylko w połowie. Musiałem ją zostawić na farmie Svena, kiedy stamtąd uciekałem...$B$BProszę. Zanieś mój ukończony dziennik Svenowi. Dokładniej opisuje, co wydarzyło się na jego farmie.$B$BChoć przez ostatnie tygodnie ten dziennik był moim jedynym towarzyszem, jeśli oddając go, uniknę spotkania ze Svenem i jego gniewem, oddam go z radością!', 'Wróć do Svena z ukończonym dziennikiem Dygota.', '', '', '', '', '', '', 0),
(321, 'koKR', 'Żelazo kuźni światła', 'Wraki u tutejszego wybrzeża to skazana na zagładę Trzecia Flota Kul Tiras, spalona i zatopiona przez czerwone smoki podczas ostatniej Wielkiej Wojny.$B$BFlota wypłynęła z Lordaeronu, ale płynął z nią też jeden statek – elfi niszczyciel „Latający Rybołów”. Przewoził ładunek żelaza kuźni światła i dołączył do Trzeciej Floty dla ochrony. Na ironię zakrawa, że zatonął przez te same smoki...$B$BDość historii. Wrak „Latającego Rybołowa” leży na południe od Przystani Menethilów. Jeśli znajdziesz tam żelazo kuźni światła, przynieś mi je.', 'Przeszukaj wrak „Latającego Rybołowa” na Bagniskach.', '', '', '', '', '', '', 0),
(323, 'koKR', 'Udowodnij swoją wartość', 'Morbent Fel jest nekromantą i sojusznikiem Mrocznych Jeźdźców. Rzuciłbym cię przeciw potędze Morbenta Fela, ale nie wyślę cię na tego plugawego biesa, dopóki nie poznam twojej siły.$B$B$GDowiodłeś:Dowiodłaś; mi już swojej odwagi, ale jeśli naprawdę chcesz stawić czoło nekromancie, musisz teraz wykazać się umiejętnościami w walce z jego sługami.', 'Zabij 15 szkieletowych najeźdźców, 3 szkieletowych uzdrowicieli i 3 szkieletowych stróżów, a potem wróć do Svena.', '', 'Wróć do Svena Yorgena na Cichym Brzegu w Kniei Zmierzchu.', '', '', '', '', 0),
(324, 'koKR', 'Zaginione sztaby', 'Gdy wyjmujesz jedyną sztabę kuźni światła z przemokniętej skrzyni, staje się jasne, że resztę ukradły murloki. Poluj na murloków grabieżców w pobliżu wraku „Latającego Rybołowa”, by odzyskać zaginione żelazo kuźni światła.', 'Zbierz 5 sztab kuźni światła, a potem wróć do Glorina Stalobrwego na Bagniskach.', '', 'Wróć do Glorina Stalobrwego w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(401, 'koKR', 'Zaczekaj, aż Sirra skończy', 'Prawie skończyłem tłumaczyć ten liścik. Wróć za kilka chwil, powinienem już mieć gotowe.', 'Zaczekaj chwilę, a potem znów porozmawiaj z Sirrą Von\'Indi.', '', '', '', '', '', '', 0),
(402, 'koKR', 'Sirra jest zajęty', 'Przykro mi, ale w obecnym stanie miasta mam inne obowiązki. Może później, jeśli przeżyjemy, dokończę to tłumaczenie.', 'Wróć później do Sirry i sprawdź, czy nadal jest zajęty.', '', '', '', '', '', '', 0),
(453, 'koKR', 'Na tropie mrocznej postaci', 'Powodzenia, $N. Mam nadzieję, że znajdziesz tego gościa, i to żywego.$B$BJeśli opuścił bezpieczne Mroczne Włości, mógł paść łupem dzikich bestii.', 'Odnajdź mroczną postać. Twoje wskazówki:$B$BNie pochodzi z Mrocznych Włości.$B$BJest nerwowy i cały dygocze.$B$BOpuścił Mroczne Włości i udał się na zachód.', '', '', '', '', '', '', 0),
(526, 'koKR', 'Sztaby kuźni światła', 'Może i $gznalazłeś:znalazłaś; w tej skrzyni jedną sztabę kuźni światła, ale to za mało, żeby wykuć coś porządnego!$B$BWróć tam i poszukaj więcej. Może murloki kręcące się wokół wraku mają przy sobie sztaby kuźni światła.', 'Zbierz 5 sztab kuźni światła, a potem wróć do Glorina Stalobrwego na Bagniskach.', '', 'Wróć do Glorina Stalobrwego w Przystani Menethilów na Bagniskach.', '', '', '', '', 0),
(1041, 'koKR', 'Szlak karawan', 'Okazuje się, że się co do ciebie myliłem, a to nie zdarza się codziennie.$b$bTak się składa, że pamiętam tę Velinde, której szukasz. Nie co dzień nocna elfka, kapłanka, chce podróżować z brudną, starą – ale świetnie spełniającą twoje potrzeby przewozowe! – karawaną taką jak moja.$b$bRozdzieliliśmy się w drodze na północ, ona kierowała się do Mrocznych Włości. Tamtejszy urzędnik prowadzi przeróżne rejestry. Może wiedzieć coś przydatnego.$b$bUważaj w dżungli, to śmiertelnie niebezpieczne miejsce nawet w najlepszych czasach.', 'Porozmawiaj z urzędnikiem Daltrym w Mrocznych Włościach.', '', 'Porozmawiaj z urzędnikiem Daltrym w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(1042, 'koKR', 'Rodzina Carevinów', 'Nie, nie mam żadnych zapisów o tym, by Velinde Gwiezdna Pieśń zatrzymała się w Mrocznych Włościach... choć, jeśli pozwolisz, trudno mi sobie wyobrazić nocną elfkę kapłankę wynajmującą pokój w karczmie, rozumiesz, co mam na myśli?$b$bAle o tych wilkołakach, o których wspominasz, coś słyszałem. Ledwie parę dni temu Calor przyszedł do miasta z pękiem ich łbów. Współpracuje z rodziną Carevinów – łowcami demonów, nieumarłych i innych potworności. Porozmawiaj z Jonathanem, to głowa rodu.', 'Porozmawiaj z Jonathanem Carevinem w Mrocznych Włościach.', '', '', '', '', '', '', 0),
(1043, 'koKR', 'Kosa Eluny', 'Twoja opowieść brzmi prawdziwie... Nie do końca rozumiem twoje pobudki, ale jeśli twoje sprawy w Kniei Zmierzchu wiążą się z tępieniem worgenów, choćby i kilku, mogę zrezygnować ze zrozumienia na rzecz wyników.$b$bNa południu jest kopalnia opanowana przez worgeny... Pojawiły się znikąd, ale z tego, co wiemy, właśnie tam spotkano je po raz pierwszy.$b$bZajmij się swoimi sprawami, ale proszę, jeśli znajdziesz coś ważnego, podziel się tym ze mną. Przyjmiemy każdą pomoc w naszej wojnie ze złem.', 'Poszukaj śladów Kosy Eluny, a potem wróć do Jonathana Carevina w Mrocznych Włościach.', '', 'Wróć do Jonathana Carevina w Mrocznych Włościach w Kniei Zmierzchu.', 'Znajdź ślady Kosy Eluny', '', '', '', 0),
(1372, 'koKR', 'Prawda i tylko prawda', 'Nasz oddział ekspedycyjny wysłano z rozkazu Varimathrasa, by zbadał południowe krainy Azeroth.$b$bPodczas zwiadu zauważyłem ludzkiego infiltratora, który szpiegował Nawiedzisko Żebraka. Zanim zdążyłem go pojmać, nasi orczy... bracia... schwytali go i zabrali do Stonardu, swojej twierdzy na Moczarach Smutków.$b$bChcę... pomóc... naszym orczym sojusznikom. Nie zauważyli naszego obozu, ale mimo to chcę wyciągnąć do nich pomocną dłoń.$b$bRazem z Faustinem przygotuj... serum prawdy dla naszego przyjaciela w Stonardzie.', 'Porozmawiaj z aptekarzem Faustinem w Nawiedzisku Żebraka.', '', '', '', '', '', '', 0),
(1383, 'koKR', 'Prawda i tylko prawda', 'Mam na myśli idealne serum. Rozprawi się z prawdą dokładnie tak, jak z prawdą należy się rozprawić.$b$bDo tej mikstury potrzebuję kilku serc cienistych panter z Moczarów. Potrzebuję też zaczarowanego grzyba, który porasta władcę bagien żyjącego w tamtych stronach. Jestem pewien, że ktoś tak zdolny jak ty, $n, zdoła go przekonać, by się nim podzielił.$b$bOstatnim składnikiem serum jest krew śniącego smoczego pisklęcia, takiego jak te, które żyją przed jaskinią Ithariusa na moczarach.$b$bA teraz ruszaj!', 'Aptekarz Faustin w Nawiedzisku Żebraka potrzebuje 5 serc cienistych panter, grzyba władcy bagien i trochę krwi zielonego smoczego pisklęcia.', '', 'Wróć do aptekarza Faustina we Dworze Mgłopłaszcza w Kniei Zmierzchu.', '', '', '', '', 0),
(1388, 'koKR', 'Prawda i tylko prawda', 'Wszystko idzie zgodnie z planem, $n. Daj to serum prawdy tropicielowi śmierci Zraedusowi, a on pokaże ci, jak je... właściwie podać.$b$bHaha!', 'Daj Serum prawdy Faustina tropicielowi śmierci Zraedusowi w Nawiedzisku Żebraka.', '', '', '', '', '', '', 0),
(1391, 'koKR', 'Prawda i tylko prawda', 'Musimy działać z pewną dyskrecją. W końcu nie wparujesz tam tak po prostu i nie przekonasz tego głupca, żeby wypił miksturę Faustina, prawda?$b$bAle jeśli czegoś ludzie nie potrafią odmówić, to gorzały. Wmieszam serum Faustina do tego piwa. Gwarantuję, że ten biedny naiwniak nie zawaha się ani chwili, gdy przyjdzie mu wychylić kufel duszkiem.$b$bRuszaj szybko do Stonardu na Moczarach Smutków, $n. I zachowaj naszą małą misję w tajemnicy...', 'Zanieś Napar Zraedusa infiltratorowi Marksenowi w Stonardzie.', '', '', '', '', '', '', 0),
(1395, 'koKR', 'Zaopatrzenie dla Strażnicy Otchłani', 'Tę skrzynię kamieni mocy trzeba dostarczyć do Strażnicy Otchłani na Jałowych Ziemiach. Kamienie nie utrzymają mocy długo, więc nie możemy wysłać ich z następną karawaną.$B$BTo ty musisz je zanieść, i to szybko.$B$BDostarcz je kwatermistrzowi Lungertzowi w Strażnicy Otchłani. Aby tam dotrzeć, musisz udać się na wschód przez Przełęcz Wichrowej Zguby, potem dalej na wschód przez Moczary Smutków, a następnie na południe przez Jałowe Ziemie.$B$BZachowaj ostrożność, $N. Będziesz przemierzać niebezpieczne krainy, a nie wolno ci zawieść.', 'Dostarcz Skrzynię kamieni mocy kwatermistrzowi Lungertzowi, zanim kamienie stracą moc.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(5, 'koKR', 'Potrzebujesz kotlecików krabowych, tak? Cóż, może uda mi się coś dla ciebie upichcić...', 0),
(55, 'koKR', 'Morbent Fel został pokonany. Mroczni Jeźdźcy wciąż są na wolności, ale spełniła się choć cząstka tego, na co liczyłem wbrew wszelkiej nadziei.$b$b$GDokonałeś:Dokonałaś; niemożliwego, a twoje czyny na zawsze pozostaną w legendach Kniei Zmierzchu.$b$bIdź, $N. A może pewnego dnia los znów sprowadzi cię do mnie...', 0),
(56, 'koKR', 'Wspaniale, $N. Za służbę mieszkańcom Mrocznych Włości zostaniesz $gnagrodzony:nagrodzona;.', 0),
(57, 'koKR', 'Mieszkańcy Mrocznych Włości dziękują ci, $N. $GDowiodłeś:Dowiodłaś;, że jesteś $gwielkim sojusznikiem:wielką sojuszniczką; Nocnej Straży.', 0),
(58, 'koKR', 'W imieniu mieszkańców Mrocznych Włości i jako przywódczyni Nocnej Straży dziękuję ci, $N, za odwagę i poświęcenie. Niech Światło oświetla twoje ścieżki.', 0),
(66, 'koKR', 'Ach, więc przysłała cię Madame Eva...', 0),
(79, 'koKR', 'No proszę, $gspisałeś:spisałaś; się jak prawdziwy detektyw, $N.', 0),
(80, 'koKR', 'Ależ tak! Pismo na tej kartce rzeczywiście zgadza się z podpisami w rejestrze.', 0),
(90, 'koKR', 'Świetna robota, $N! Delektuj się przysmakiem zwanym przyprawionym szaszłykiem z wilka!', 0),
(93, 'koKR', 'Ach tak, niezła garść nóg! Tylko doprawię je moimi tajnymi przyprawami (nie podglądać!) i niech sobie trochę poprzebierają nóżkami na patelni...$B$BA choć zmierzchowe kotleciki krabowe to moja specjalność i nie zdradzę ich przepisu, oto przepis na danie niemal równie dobre.', 0),
(95, 'koKR', 'Leży tu kopczyk ziemi usypany w pośpiechu, jakby ktoś musiał coś ukryć... i nie miał na to wiele czasu.', 0),
(97, 'koKR', 'Wiedziałam! Dobra robota, $N.', 0),
(98, 'koKR', 'Wiem, $N: Stalvan nie żyje. Poczułam, jak przez skażony las przetacza się fala nadziei. Knieja Zmierzchu raz na zawsze uwolniła się od jego żądzy krwi. Moją radość mącą jednak myśli o tych, którzy padli ofiarą tej potwornej bestii. Mimo to jesteś $godważny i przebiegły:odważna i przebiegła;.', 0),
(101, 'koKR', 'Bardzo mądrze, $N. Ten Totem udręki pomoże ci się chronić przed złem, które czai się w całym Azeroth i poza nim. Gdy poczujesz zagrożenie, weź totem do ręki i znajdź otuchę w jego magicznej aurze. Bądź $gdzielny:dzielna;, $N. Będziesz potrzebować całej odwagi, na jaką cię stać, bo w twojej przyszłości widzę wiele przelanej krwi.', 0),
(133, 'koKR', 'Ach, dziękuję. Nadadzą się w sam raz!', 0),
(134, 'koKR', 'Dzięki niech będą Nekro... to znaczy, dzięki TOBIE, $N! W pełni $gzasłużyłeś:zasłużyłaś; na nagrodę.$B$BAha! Radość! Radosne noce przede mną!!', 0),
(148, 'koKR', 'Ach, potrzebujesz nici z włosów ducha? Obawiam się, że nie mam jej na składzie, ale mogę ci ją zrobić... jeśli dostarczysz mi włosy ducha.', 0),
(149, 'koKR', 'Co to? Grzebień? Jest śliczny! Sunie przez moje włosy, jakby nie były tymi sztywnymi, strąkowatymi okropieństwami, którymi są.$B$BOch, gdybym tylko miała lustro...', 0),
(154, 'koKR', 'Zrobię z tego szpulkę nici z włosów ducha i jeszcze zostanie mi kilka pasm. Masz tu parę monet za te dodatkowe pasma.', 0),
(156, 'koKR', 'Dobrze, masz kwiaty zgnilizny. Powiem też Althei Ebonlocke z Nocnej Straży, że $gtępiłeś:tępiłaś; szkielety.$B$BStrzeżenie mieszkańców Mrocznych Włości to dla Nocnej Straży ponure brzemię, więc wieść, że inni pomagają powstrzymać falę potworów w Kniei Zmierzchu, na pewno zostanie przyjęta z radością.', 0),
(157, 'koKR', 'Cudownie! Nada się znakomicie...$b$bProszę, $N, przyjmij to jako zapłatę za twój szlachetny uczynek.', 0),
(158, 'koKR', 'Potrzebujesz soku zombie, tak? Hmm... to mocny trunek – rzadko ktoś o niego prosi.', 0),
(159, 'koKR', 'Stokrotne dzięki, $N. Rozgrzewasz serce starca swoją głupo-... to znaczy... swoją dobrocią!$b$bProszę, $gprzyjacielu:przyjaciółko;. Przyjmij to w dowód mojej wdzięczności.', 0),
(160, 'koKR', '<Ello przygląda się listowi...>$B$BCo to za język? Wygląda na starożytny... Nie potrafię tego odczytać.', 0),
(163, 'koKR', 'Nie! Proszę, nie zabijaj mnie! To tylko ja... Dygot!! Oni są wszędzie... Nie mogę przed nimi uciec! Potwory na Kruczym Wzgórzu? N-n-n-nie... niemożliwe. Tylko niegroźny Dygot.', 0),
(164, 'koKR', 'Te zapasy bardzo się przydadzą. Pomoc rodziny Carevinów zawsze jest mile widziana. Proszę, drobiazg za fatygę.', 0),
(165, 'koKR', 'Hehe, ach tak... oczywiście, Carevinowie.$B$BNie, nic się nie stało, ale trudno mi teraz chodzić do miasta. Drogi są niebezpieczne, a ja nie młodnieję. Może wyświadczysz staremu człowiekowi kilka przysług?', 0),
(173, 'koKR', 'Imponujące, $N. Wygląda na to, że potrafisz o siebie zadbać. Może znajdzie się wyzwanie bardziej odpowiednie dla kogoś o twoich umiejętnościach.$b$bTo jednak ciekawe... Worgeny zdają się pojawiać znikąd. Ale przy tych wszystkich dziwnych stworzeniach, które przekroczyły nasze granice, to chyba tylko jedno z wielu zmartwień.', 0),
(174, 'koKR', 'Doskonale, $N. Pierwszy krok za nami!', 0),
(175, 'koKR', 'Ależ tak, miałam kiedyś lusterko.', 0),
(177, 'koKR', 'Przewspaniale! Nada się doskonale. Stokrotne dzięki!', 0),
(181, 'koKR', 'Nareszcie! Urządzenie do obserwacji gwiazd jest gotowe! Dziękuję, $N. Teraz mogę kontynuować badania...', 0),
(221, 'koKR', 'Dobrze się $gspisałeś:spisałaś; w walce z mrocznymi biegaczami, $N. Ale wygląda na to, że ich liczba jest niewyczerpana. Za każdym razem, gdy robimy postępy, na miejsce poległych zjawiają się nowi.$b$bJaka zła moc ich tu przyciąga? Dlaczego przybyli, by nękać naszą nieszczęsną krainę...$b$bZaufam mistrzowi Carevinowi. Bez wątpienia dotrze do sedna problemu.', 0),
(222, 'koKR', '$N, szczerze mówiąc, nie sądziłem, że zajdziesz tak daleko, ale najwyraźniej trzeba się z tobą liczyć. Jeśli chcesz oficjalnie przyłączyć się do walki mistrza Carevina, chętnie napiszę dla ciebie list polecający.', 0),
(223, 'koKR', 'Wybacz mi to chłodne przyjęcie, $N, ale jak zapewne widzisz, jestem niezwykle zajętym człowiekiem. Widzę, że $gzrobiłeś:zrobiłaś; wrażenie na Calorze – a zapewniam, że to nie lada wyczyn – i że cię polecił.$b$bKręcą się tu podejrzane typy, $N, a przyda nam się pomoc każdego, kto się wykazał. Walczymy z demonami, nieumarłymi i tymi, którzy gotowi są udzielać im pomocy. Bądź $gczujny:czujna;, bądź $gostrożny:ostrożna; i nie ufaj nikomu, kto nie wesprze naszej sprawy.$b$bChwała w Świetle.', 0),
(225, 'koKR', 'Morgan Ladimore?$b$bAch, tak, oczywiście. Jego historia była długa i smutna. Znałem go dobrze, zanim wyruszył na wojnę, ale wtedy widziałem go po raz ostatni. Był szlachetnym i dobrym człowiekiem, lecz spotkał go zły koniec.$b$bZaraz, powinienem mieć tu coś, co opowie tę historię lepiej niż moje wspomnienia...', 0),
(226, 'koKR', 'O, dobrze. Nieźle $gprzetrzebiłeś:przetrzebiłaś; tę sforę, a skoro wilki nie kąsają nas już po piętach, możemy skupić myśli na Morbencie Felu.$B$BProszę, weź trochę tych błyskowych pakunków. Robią je w mieście, a sporo z nich przekazano Svenowi na potrzeby jego sprawy.', 0),
(227, 'koKR', 'Morgan Ladimore? Nigdy nie słyszałam o...$b$bAch, chodzi ci o Mor\'Ladima! Rozumiem, że nie znasz tej historii?$b$bCóż, opowiem ci ją w skrócie. Po Kniei Zmierzchu błąka się nieumarły, który nazywa siebie Mor\'Ladimem. Z tego, co ustaliliśmy, to ożywione ciało Morgana Ladimore\'a, o którym najwyraźniej już wiesz. Sprawia nam mnóstwo kłopotów – napada na wartowników na patrolu i zabija ludzi.$b$b<Mierzy cię wzrokiem.>$b$bWyglądasz na kogoś, kto da sobie radę. Może zdołasz sprawić, by spoczął w pokoju.', 0),
(228, 'koKR', '$GZabiłeś:Zabiłaś; go? To nie lada wyczyn, $N! W imieniu mieszkańców Mrocznych Włości i Nocnej Straży dziękuję ci.$B$BAch... jest jednak jeszcze jedna drobna sprawa...', 0),
(229, 'koKR', 'Tak? Mój ojciec...$B$B<Spuszcza wzrok.>$B$BGdybym tylko... mogła coś dla niego zrobić... Gdybym tylko porozmawiała z nim, zanim...', 0),
(230, 'koKR', '<Sven czyta strony książki, po czym gwałtownie ją zatrzaskuje.>$B$BTa mroczna postać, którą widziałem, była świadkiem śmierci mojej rodziny! Chciałbym zadać temu człowiekowi kilka pytań... gdybym tylko wiedział, kim jest!', 0),
(231, 'koKR', '<Na wietrze rozlega się upiorny głos...>$B$BCo to...? Sarah? Czyżby wciąż żyła? Ciężar spada mi z ramion...$B$B$N. Weź mój miecz, Archeusa. Skoro moja dusza zazna spokoju, nie jest mi już potrzebny. Wykuto go, by czynił dobro, i choć okazałem się niegodny, by go dzierżyć, może ty poniesiesz dzięki niemu Światło dalej.$B$BLys, ukochana moja...', 0),
(240, 'koKR', 'Aha! Dziękuję, $N. Właśnie tego mi było trzeba!$B$BI proszę, pozwól, że ci za nie zapłacę!', 0),
(245, 'koKR', 'Ach! $GWróciłeś:Wróciłaś;. I to chyba bez większego uszczerbku. Oczywiście, $N, Nocna Straż jest ci wdzięczna, a ja obiecałem ci nagrodę, więc proszę.', 0),
(251, 'koKR', '<Sirra zaczyna tłumaczyć liścik...>', 0),
(252, 'koKR', '<Ello czyta list... i blednie. Potem patrzy na ciebie...>$b$bChoć pomoc, której $gudzieliłeś:udzieliłaś; Abercrombiemu, mogła wynikać z dobroci serca, twoje czyny ściągnęły zgubę na nasze miasto.$b$b<Ello pogrąża się w myślach...>', 0),
(253, 'koKR', '$GDokonałeś:Dokonałaś; tego! Magia zawarta w jego sercu uchroni nas przed złem Balsamisty i roztoczy nad Mrocznymi Włościami potężną tarczę.$B$B$GUczyniłeś:Uczyniłaś; wielką rzecz dla naszego ludu, $N. Twoje imię na zawsze pozostanie w naszych kronikach.', 0),
(254, 'koKR', 'Rozgrzebujesz na wpół sypką ziemię na grobie... i odsłaniasz resztki trumny.$B$BCzujesz drgania – w środku coś drapie szponiastymi palcami i zgrzyta zgniłymi zębami...$B$BCzy otworzysz trumnę i wydobędziesz serce Balsamisty?', 0),
(262, 'koKR', 'Hmm... Ktoś niedawno trzymał tę książkę w rękach, ktoś, kim kieruje żądza zemsty. Ale ślady, które na niej pozostały – przynajmniej te po pierwotnym właścicielu – są słabe.$b$bMogę jednak powiedzieć, że pierwotny właściciel tej książki nie pochodzi z Mrocznych Włości.', 0),
(265, 'koKR', 'Ach, tak. Miesiąc temu sprzedałem tę książkę pewnemu podejrzanemu typowi. Nie przedstawił się, ale był nerwowy, cały dygotał i ciągle oglądał się przez ramię.$B$BMam nadzieję, że to ci pomoże...', 0),
(266, 'koKR', 'O tak, pamiętam tę książkę. Jej właściciel wynajął pokój na kilka dni, a noce spędzał przy barze, pisząc.$B$BWyjechał z miasta w pośpiechu, mamrocząc, że ściga go... coś. Ostatnio widziałem, jak kierował się na zachód, szukając nowej kryjówki.$B$BPierwsze miejsce, na jakie trafiłby na zachodzie, to Krucze Wzgórze...', 0),
(268, 'koKR', 'Ten dziennik wiele mi wyjaśnia i wskazuje mi drogę do walki z Mrocznymi Jeźdźcami! Widziałem tych jeźdźców w Kniei Zmierzchu i widziałem, jak rozmawiali z czarownikiem Morbentem Felem w Opuszczonym Domu Rowe\'ów.', 0),
(321, 'koKR', 'Skrzynia jest przesiąknięta wodą, a jej ścianki popękane. Zarówno wnętrze, jak i zewnętrzną stronę skrzyni znaczą liczne ślady pazurów... jakby murloki przeszukały ją i ukradły skarb.$b$bAle głęboko w skrzyni tkwi jedna sztaba kuźni światła. Niestety, żeby zdobyć dość metalu na wykucie broni, potrzeba ich znacznie więcej.', 0),
(323, 'koKR', 'Twoich umiejętności bojowych, $N, nie sposób podważyć. Twoja determinacja może jeszcze sprawić, że doczekamy końca Morbenta Fela!', 0),
(324, 'koKR', 'Ach, $gznalazłeś:znalazłaś; je! No to przekujmy to żelazo kuźni światła na coś pożytecznego, co?', 0),
(401, 'koKR', 'No i proszę. Przetłumaczone...$B$B<Powietrze gęstnieje, jakby nad krainą zaciągnięto grubą, czarną kurtynę...>', 0),
(453, 'koKR', '<Dygot wzdycha...>$B$BTak, to ja jestem autorem tej książki. W końcu mnie $gznalazłeś:znalazłaś;, co?$B$BCóż, jeśli $gprzeczytałeś:przeczytałaś; ten dziennik... to znasz tylko połowę historii!', 0),
(526, 'koKR', 'Ach, $gznalazłeś:znalazłaś; je! No to przekujmy to żelazo kuźni światła na coś pożytecznego, co?', 0),
(1041, 'koKR', 'Przy tych wszystkich dziwnych zdarzeniach ostatnich lat staram się jak najstaranniej notować przyjezdnych. Nigdy nie wiadomo, kiedy się to przyda... choć zwykle, kiedy się przydaje, sprawa nie jest przyjemna. Nie żebym coś sugerował co do tej Velinde, której szukasz.', 0),
(1042, 'koKR', 'Mroczne to czasy. Każda kołysząca się gałąź szepcze złe wieści, a pod każdym kamieniem czai się zło.$B$BA w takich czasach nieznajomy wchodzi do mojego domu i wypytuje o worgeny... Nie będę przepraszał za swoje podejrzenia – chcę tylko odpowiedzi.$B$BI dostanę je.', 0),
(1043, 'koKR', 'Ciekawą historię opowiadasz, $N. Choć wpływy rodziny Carevinów nie są na tyle duże, byśmy mogli dotrzeć do źródła tych kłopotów i raz na zawsze z nimi skończyć, zrobimy, co w naszej mocy, by powstrzymać rozrost worgeńskiej plagi w Kniei Zmierzchu.$B$BJuż poleciłem Calorowi, by uczynił to swoim najważniejszym zadaniem.', 0),
(1372, 'koKR', 'Zraedus właśnie opowiadał mi o tym wścibskim małym infiltratorze, zanim $gprzybyłeś:przybyłaś;.$b$bSpory kłopot, doprawdy. Ostatnie, czego nam trzeba, to natręt węszący wokół Nawiedziska Żebraka.$b$bJestem pewien, że orkowie ze Stonardu bardzo chcieliby usłyszeć, co nasz przyjaciel ma do powiedzenia. Skoro są naszymi sojusznikami, ekhm, musimy im pomóc wydobyć z tego człowieka wszelkie informacje.$b$bPracuj ze mną, $N, a dostarczymy do Stonardu serum prawdy.$b$bZa Hordę!$b$b...dobrze to powiedziałem?', 0),
(1383, 'koKR', 'Wspaniale, $N! I w samą porę. Według Zraedusa infiltrator wylizał się z ran i jest gotów na przesłuchanie przez orków.$B$BDaj mi tylko chwilę, bym przygotował truciz... to znaczy, serum prawdy.', 0),
(1388, 'koKR', 'Wiedziałem, że stary Faustin wymyśli coś dobrego! $GOkazałeś:Okazałaś; się ogromną pomocą, bez dwóch zdań.$B$BA teraz przejdźmy do rzeczy, dobrze?', 0),
(1391, 'koKR', 'Napitek dla mnie? Jak miło. Od kilku dni nie pozwalali mi nic pić. Pozwól, że to wypiję, a potem powiem ci, czego się dowiedziałem...', 0),
(1395, 'koKR', 'Ach, kamienie mocy! Magowie ucieszą się na ich widok!$B$BStokrotne dzięki, $N. Wiem, że podróż z Mrocznych Włości nie była łatwa.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(55, 'koKR', 'Czy Morbent Fel został pokonany?!', 0),
(56, 'koKR', '$GZabiłeś:Zabiłaś; tych wojowników i magów?', 0),
(57, 'koKR', 'Wróć do mnie, gdy zabijesz 15 szkieletowych biesów i 15 szkieletowych poczwar, $N.', 0),
(58, 'koKR', 'Potrzebuję twojej pomocy, $N. Udaj się na cmentarz na północnym zachodzie i oczyść wschodnie mauzoleum z 20 roznosicieli zarazy.$B$BWróć do mnie, gdy wykonasz zadanie.', 0),
(79, 'koKR', 'Oby to było coś ważnego, $N. Pokaż, co masz, i opowiedz swoją historię. Ale na Światło, streszczaj się. Obrona Mrocznych Włości jest dla mnie najważniejsza. Nie mam czasu do stracenia na tropy prowadzące donikąd.', 0),
(80, 'koKR', 'Znowu tutaj, $N? Co masz tym razem?', 0),
(90, 'koKR', 'Udało ci się już zdobyć 10 chudych wilczych udźców? A zioła od Felicii z Wichrogrodu?', 0),
(93, 'koKR', 'Witaj, $N. $GZdobyłeś:Zdobyłaś; już te ciągnące się pajęcze nogi?', 0),
(101, 'koKR', 'Przynieś mi 10 kłów ghuli, 10 palców szkieletów i 5 fiolek pajęczego jadu. Zaklnę dla ciebie Totem udręki, który zrani każdego, kto spróbuje użyć wobec ciebie przemocy.', 0),
(133, 'koKR', 'Chyba słyszę, jak stado ghuli kręci się za domem – lepiej szybko postawię to straszydło! $GZdobyłeś:Zdobyłaś; dla mnie te żebra ghuli?', 0),
(134, 'koKR', 'Masz moją skrzynię? Jeśli tak, to proszę... oddaj mi ją szybko!', 0),
(149, 'koKR', 'Och, proszę, nie patrz na mnie! Wydarłam sobie te oczy własnymi rękami, a mimo to wciąż czuję twoje spojrzenie!$B$BJestem ohydna! Ohydna! Proszę, odwróć wzrok!!', 0),
(154, 'koKR', 'Czuję, że $gwidziałeś:widziałaś; Ślepą Mary. Masz mój grzebień...?', 0),
(156, 'koKR', 'Cześć, $N. Masz już dla mnie te kwiaty zgnilizny?', 0),
(157, 'koKR', 'Muszę rozwiesić nić z włosów ducha wokół drzwi i okien, żeby nie wpuścić nieproszonych duchów. $GZdobyłeś:Zdobyłaś; ją dla mnie?', 0),
(159, 'koKR', 'Potrzebuję tego soku zombie, żeby się ogrzać w te zimne, ciemne noce. $GZdobyłeś:Zdobyłaś; go dla mnie?', 0),
(160, 'koKR', 'Abercrombie...? Nie znam nikogo o tym nazwisku. Mówisz, że masz dla mnie list od tego całego Abercrombiego?$B$BNo to pokaż...', 0),
(163, 'koKR', 'Ach, $N! Już z powrotem? Pewnie znów $gbyłeś:byłaś; na łowach? Nie martw się, jeśli coś poszło nie tak – na dłuższą metę wyjdzie ci to na dobre!$B$B...$GGorszy:Gorsza; i tak już nie będziesz...', 0),
(164, 'koKR', 'Wyglądasz na $gtwardego:twardą;, $N. $GPrzyszedłeś:Przyszłaś; przyłączyć się do naszej walki?', 0),
(173, 'koKR', '$N, jak idą łowy?', 0),
(174, 'koKR', '$GZnalazłeś:Znalazłaś; już biegłego inżyniera, który zrobi brązową rurę?', 0),
(177, 'koKR', 'Pokazałem Cogowi zaczątki naszej maszyny do oglądania gwiazd. Był pod wrażeniem. Czy udało ci się znaleźć coś, co odbija światło?', 0),
(181, 'koKR', 'Czy udało ci się przekonać Zzarc\'Vula, żeby pożyczył nam monokl do naszego eksperymentu?', 0),
(221, 'koKR', 'Już z powrotem, $N? Mam nadzieję, że nie $gprzyszedłeś:przyszłaś; mi powiedzieć, że się $gpoddałeś:poddałaś;.', 0),
(222, 'koKR', 'Budzą grozę, prawda? Ale nie lękaj się, $N – ci, którzy stoją po stronie Światła, nigdy nie upadną!', 0),
(223, 'koKR', 'Tak, o co chodzi? Streszczaj się, mam pilne sprawy na głowie.', 0),
(226, 'koKR', 'Wciąż polujesz na wilki...?', 0),
(228, 'koKR', 'Nie dziwię się, że masz z nim kłopoty, $N. Straciliśmy przez Mor\'Ladima kilku naszych najsilniejszych wartowników.', 0),
(230, 'koKR', 'Co $gznalazłeś:znalazłaś;?? Proszę, pokaż mi to...', 0),
(231, 'koKR', 'Zostaw mnie w spokoju...', 0),
(240, 'koKR', '$N, jesteś! Masz moje jedzenie?!?', 0),
(245, 'koKR', 'Lepiej uważaj przy tych pająkach. Straciłem przez nie kilku ludzi i wierz mi, widok człowieka wiszącego głową w dół w ich sieci, gdy jad zaczął go już zmiękczać, nie należy do przyjemnych.$B$BNie chciałbym zobaczyć, jak któryś z tych robali zjada cię na obiad.', 0),
(251, 'koKR', 'Liścik od Abercrombiego, tego pustelnika? Nie znam go, ale jeśli mieszka przy cmentarzu, to jedno wiem na pewno: mózg mu przegnił!', 0),
(252, 'koKR', 'Ach, czy liścik jest już przetłumaczony? Proszę, pokaż mi go...', 0),
(253, 'koKR', '$GZnalazłeś:Znalazłaś; już grób Elizy? Masz serce Balsamisty?', 0),
(262, 'koKR', 'Jeśli masz coś, co należy do mrocznej postaci, której szukasz, pokaż mi to. Może zdołam wywróżyć coś o właścicielu.', 0),
(265, 'koKR', 'Czasem sprzedaję czyste księgi uczonym i magom albo każdemu, kto chce prowadzić dziennik.$B$BDobrze pamiętam wszystkich, którym sprzedałem książkę w ciągu ostatnich kilku miesięcy...', 0),
(266, 'koKR', 'Do „Szkarłatnego Kruka” nie zagląda już tylu gości co dawniej, ale wciąż zatrzymują się u nas podróżni.$B$BJeśli opiszesz osobę, której szukasz, może ją sobie przypomnę.', 0),
(268, 'koKR', 'Czy $gdowiedziałeś:dowiedziałaś; się, kim była mroczna postać?', 0),
(323, 'koKR', 'Walcz zawzięcie, $N. I nie poddawaj się rozpaczy, bo rozpacz to największa broń zła.', 0),
(324, 'koKR', '$GZnalazłeś:Znalazłaś; potrzebne ci żelazo kuźni światła?', 0),
(453, 'koKR', 'Kim jesteś?? Zostaw mnie w spokoju!', 0),
(526, 'koKR', '$GZnalazłeś:Znalazłaś; potrzebne ci żelazo kuźni światła?', 0),
(1043, 'koKR', 'Las jest zdradliwy dla nieprzygotowanych. Trzymaj broń pod ręką, a rozum jeszcze bliżej, bo inaczej twoja następna wyprawa do nawiedzonego lasu może okazać się ostatnią.', 0),
(1383, 'koKR', 'Ten infiltrator w Stonardzie na pewno... się otworzy... po wypiciu mojego specjalnego serum. Haha!$b$bZdobycie potrzebnych składników wcale nie jest łatwe. Cieniste pantery są na Moczarach pospolite, ale zebranie tylu serc, ilu potrzebujemy, może zniechęcić. A władca bagien bywa taki grymaśny.$b$b', 0),
(1388, 'koKR', 'Mam nadzieję, że $gokazałeś się przydatny:okazałaś się przydatna; naszemu drogiemu przyjacielowi, aptekarzowi Faustinowi.', 0),
(1391, 'koKR', 'Zlituj się nade mną! Mam informacje, które wykraczają poza podział na Przymierze i Hordę. Choć nie sympatyzuję z Hordą, dzieje się tu polityczna zdrada, którą trzeba ujawnić!', 0),
(1395, 'koKR', 'Witaj! Nie zwracaj uwagi na całe to zamieszanie, w Strażnicy Otchłani to zwykły dzień.$B$BMasz coś dla mnie?', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(264, 0, 'koKR', 'Spocznij, $N. Jeśli tylko tędy przejeżdżasz, radzę trzymać się dróg i podróżować wyłącznie za dnia. Jeśli zaś masz sprawy tu, w Mrocznych Włościach, zastanów się, czy nie oddać swoich sił na służbę Nocnej Straży. Naszych umiejętności nikt nie kwestionuje, ale jest nas niewielu.', 0),
(265, 0, 'koKR', 'Od dawna wyczuwam twoje nadejście, $n. Zapisano je w układzie gwiazd.', 0),
(272, 0, 'koKR', 'Witaj, witaj! Witaj w mojej kuchni, $gszanowny panie:szanowna pani;! To tu powstają wszystkie najwspanialsze przysmaki tawerny „Szkarłatny Kruk”. Ach, tylko poczuj ten cudowny aromat!', 0),
(288, 0, 'koKR', 'Co?!? Aha. Nie wyglądasz na złodzieja z Nieskornych... ani na kogoś z Nocnej Straży. Zlituj się nad biedakiem, co?', 0),
(289, 0, 'koKR', 'Hę? Witaj, $N. Musisz być $godważny:odważna;, skoro $gdotarłeś:dotarłaś; tu mimo tych wszystkich stworów, które się tu kręcą!$B$BSkoro już tu jesteś, może pomożesz staremu pustelnikowi...', 0),
(633, 0, 'koKR', 'Nadeszły mroczne czasy, $N... Już wkrótce stracimy wszystko... Gdy Światło opuści wszystkich poza tymi, którzy naprawdę kroczą w jego blasku.', 0),
(663, 0, 'koKR', 'Rodzina Carevinów walczy o zwycięstwo w Świetle. Moim obowiązkiem wobec Światła jest oddać życie w ich bitwie z nieumarłymi. Mistrz Carevin powierzył mi wytępienie plugawych worgenów w Kniei Zmierzchu. Może mi pomożesz?', 0),
(5393, 0, 'koKR', 'Strażnica Otchłani zawsze potrzebuje więcej zaopatrzenia – zaopatrzenia, które pomaga naszym magom w badaniach, i zaopatrzenia, dzięki któremu nasi obrońcy są w najlepszej formie bojowej.', 0);
