INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(22, 'koKR', '. . .jestem niemal pewien, że ona odwzajemnia teraz moje uczucia. Dziś rano położyła nawet dłoń na mojej. Gdy się uśmiecha, jej oczy rozbłyskują jak lśniące diamenty. Przepływają między nami niewypowiedziane słowa. Czuję ją w łomoczącym sercu i rozpalonych żyłach.', 0),
(23, 'koKR', '. . .gniew i furia, o których istnieniu nie miałem pojęcia! Jak ona śmiała. Gdy uczyłem Gilesa znaczenia liczb, Tilloa stanęła przede mną z zalotnikiem – i to trzymając go za rękę na oczach wszystkich! Cóż za nieokrzesany młodzieniec. Zamiast mnie należycie przedstawić, Tilloa rzuciła tylko: „Och, to tylko mój nauczyciel, wujek Stalvan. Miły z niego staruszek”. Staruszek! Na to słowo policzki zapłonęły mi żarem. Jestem od niej starszy zaledwie o kilka lat, a mimo to ona zdradza. . .', 0),
(24, 'koKR', '. . .spirala rozpaczy, w którą się pogrążam. Najpierw ze mnie drwi, a teraz jest zaręczona. Niewdzięczna oszustka udawała miłość, a tak naprawdę od początku pragnęła mnie zranić. Czai się teraz we mnie czarna pustka, która rośnie z każdą chwilą na jawie. Krew, którą przeleję, jest niczym w porównaniu z łzami, które wylałem. . .', 0),
(53, 'koKR', 'Litery na tym liściku zdają się migotać i tańczyć po jego powierzchni. Nie sposób wyczytać z nich żadnego sensu...', 0),
(54, 'koKR', 'Witaj, Ello Ebonlocke, burmistrzu Mrocznych Włości. Obawiam się, że mam wieści dla twojego miasta. Grobowe wieści.\n\nWidzisz, jestem twórcą. Oszukałem okaziciela tego liściku, by pomógł mi przy moim najnowszym, najstraszliwszym dziele – potworze z ciała, kości i powykręcanego metalu! Gdy to czytasz, zapewne czeka przed moim skromnym domostwem, zgrzytając zębami, aż dam mu znak, by ruszył siać rzeź.\n\nAle wkrótce sam się przekonasz.\n\n– Balsamista', 0),
(63, 'koKR', 'Mistrzu Carevin, $gten, kto:ta, która; przynosi ten liścik, $gdowiódł:dowiodła;, że jest $gprawy:prawa; w Światłości, $gzdolny:zdolna; stawić czoła nieumarłym i demonom, które nękają granice Kniei Zmierzchu, i $ggotów:gotowa; przyłączyć się do rodu Carevinów w ich służbie Światłości. Proponowałbym zatem, byś powierzył $gtemu wojownikowi:tej wojowniczce; Światłości dalsze zadania – być może zbadanie sprawy niektórych mieszkańców miasta, podejrzanych o wspieranie wrogów Światłości. Z wyrazami oddania, Calor', 0),
(73, 'koKR', 'Groza ostatnich tygodni niemal przerasta moje siły; czuję jednak, że jeśli spiszę to, co ujrzały moje oczy, jakoś przyniesie mi to ukojenie. Więc piszę, i to jedyna pociecha, jaka mi została w te ponure dni.', 0),
(95, 'koKR', 'Zielone wzgórza Cierniodławów$B$BNasz pierwszy dzień upłynął tak dobrze, jak tylko mogą upływać pierwsze dni. Większość czasu zajęło nam poczynienie niezbędnych przygotowań do założenia obozu głównego. Znalazłem idealne miejsce przy ujściu rzeki o słodkiej wodzie. Sądząc po starych, opuszczonych pomostach w pobliżu, ktoś zamieszkiwał to miejsce dawno temu. Co zaś do pierwotnych mieszkańców, tę opowieść zdradzi jedynie czas.', 0),
(98, 'koKR', 'W latach, które nastąpiły, gdy Wichrogród zdradził Gildię Kamieniarzy, sir Erlgadin coraz bardziej gorzkniał z powodu roli szlachty w królestwie. Nie chciał już piastować pozycji, jaką ród jego ojca wywalczył mu w Izbie Szlachty.$B$BAle odbiegam od tematu. Celem tej opowieści nie jest rozprawa polityczna ani biografia. To relacja z moich polowań na grubą zwierzynę na zielonych wzgórzach Cierniodławów.', 0),
(100, 'koKR', 'Już miałem zapytać Ajeck, czemu tak mało obchodzi ją strategia dzisiejszego polowania, gdy sięgnęła do kołczanu, wyciągnęła strzałę i wypuściła ją prosto w stronę biednego Barnila. Ale to nie w Barnila celowała Ajeck. Gdy bowiem Barnil z rozdziawionymi ustami odskoczył na bok, na powierzchnię wypłynął wielki rzeczny krokoliszek ze strzałą Ajeck wbitą idealnie między dwoje wielkich ślepi.', 0),
(102, 'koKR', 'Przy jednym z takich potknięć Erlgadin położył ciężką dłoń na ramieniu Barnila. Ajeck i ja zerknęliśmy od niechcenia, przekonani, że udziela on Barnilowi zasłużonej reprymendy za nieostrożność. Erlgadin jednak powoli wskazał głową pobliskie powalone drzewo. Wpatrywały się w nas stamtąd dwa przeszywające czarne ślepia, tuż nad paszczą pełną ostrych jak brzytwa kłów.', 0),
(104, 'koKR', 'Zdobycz wprawiła całą wyprawę w świąteczny nastrój. Barnil nalał wszystkim miodu pitnego. Ale nasze świętowanie nie trwało długo. Gdy przygotowywaliśmy truchło do transportu do obozu głównego, wszystkich nas zaskoczył straszliwy ryk. Przez wszystkie te lata nie słyszałem niczego, od czego krew tak by mroziła się w żyłach.', 0),
(105, 'koKR', 'Na skalnym urwisku w górze, na tle zachodzącego słońca, dostrzegłem sylwetkę największego drapieżnego kota, jakiego kiedykolwiek widziały moje oczy. Zdołałem oddać z karabinu jedną niezgrabną salwę, ale kot nie ustąpił. Ryknął ponownie, tym razem głośniej niż za pierwszym razem, i zniknął.$B$BZebraliśmy swoje rzeczy i w ponurym milczeniu wróciliśmy do obozu.', 0),
(108, 'koKR', 'Tego dnia wyruszyliśmy na południe, podążając świeżymi tropami pantery. Wkrótce dotarliśmy do wąwozu, nad którym rozpościerał się ogromny most linowy. Na widok tego cudu inżynierii nie mogłem nie pomyśleć o opisach tej krainy autorstwa Branna. Tak często zakładano, że tutejsze trolle to prymitywna i niewykształcona rasa, a jednak gdy przyglądałem się mistrzowskiemu wykonaniu mostu, dostrzegłem kunszt, z jakim trollowi budowniczowie dokonali rzeczy pozornie niemożliwej.\n', 0),
(110, 'koKR', 'Ajeck i sir Erlgadin stali w gotowości, z bronią wymierzoną w zjeżone zarośla u stóp kołyszących się drzew. Południowe słońce prażyło nas bezlitośnie. Po skroni Erlgadina spłynęła powoli strużka potu, gdy odciągał kurek. Na dźwięk kliknięcia gęsta roślinność rozstąpiła się i na równinę wypadła wielka czarna pantera – piękny okaz.\n', 0),
(112, 'koKR', 'Jego broń gwałtownie szarpnęła mu się w rękach. Lufa odskoczyła w bok i podbiła karabin Ajeck. Ajeck właśnie w tej chwili pociągnęła za spust. Karabin, teraz niezgrabnie skierowany ku linii drzew, wypalił z wyraźnym hukiem. Stado ptaków z wrzaskiem zerwało się z koron drzew, rozpierzchając się na wszystkie strony. Z drzewa uniósł się pióropusz dymu. Z osłupieniem patrzyliśmy, jak potężny konar spada prosto na uciekającą panterę i łamie jej grzbiet.', 0),
(114, 'koKR', 'Wyruszyliśmy o pierwszym brzasku, kierując się na południe, obok Ruin Tkashi. Barnil wyraził obawę, że możemy natknąć się na członków plemienia Krwawych Skalpów. Przypomniałem mu, że Krwawym Skalpom bardziej zależy na zniszczeniu swych plemiennych wrogów, Rozłupywaczy Czaszek. Nie trzeba dodawać, że Barnila wcale to nie uspokoiło. Ja jednak miałem nabity karabin, torbę pełną prochu i trzech zabójczych łowców u boku, co rozwiewało wszelkie obawy przed wrogą zasadzką.', 0),
(115, 'koKR', 'Stawałem na polu bitwy przed górującym nade mną piekielnikiem, gdy armia Płonącego Legionu nacierała ze wszystkich stron. Przy tym nieokiełznana banda trolli wydaje się równie groźna co zając na wzgórzach Dun Morogh.\n\nMinęliśmy Ruiny Tkashi bez przygód, ku wielkiej uldze Barnila. Drużyna skierowała się następnie na zachód, ku Wielkiemu Morzu, omijając Ruiny Zul\'Kunda, leżące tuż na południe od nas. Gdy wspięliśmy się na wysokie nadmorskie klify, dostrzegliśmy pierwszego raptora.\n', 0),
(118, 'koKR', 'Nasze pospiesznie oddane strzały wystarczyły, by Barnil zdołał uciec. Zbiegł z powrotem ze wzgórza i dołączył do drużyny. Czmychnęliśmy w dżunglę, a stado dzikich raptorów biczoogonów śledziło każdy nasz ruch. Łowcy stali się zwierzyną.', 0),
(119, 'koKR', 'Poprowadziłem drużynę ku morzu w nadziei, że na brzegu znajdziemy schronienie przed raptorami. W pośpiechu zboczyliśmy jednak za daleko na północ, na niebezpiecznie wysokie wzniesienie. Błąd został popełniony. Wina była moja. Zatrzymaliśmy się tuż przed stromym urwiskiem, a raptory były zaledwie kilka kroków za nami.', 0),
(120, 'koKR', 'Postąpiłem powoli naprzód z uniesioną bronią. Przywiodłem tych dzielnych łowców na śmierć. Zginę, broniąc ich. Raptory biczoogony są wyjątkowo zajadłe, słyną z nieugaszonej żądzy krwi. Znacznie przewyższały nas liczebnie. Ale niech mnie diabli, jeśli pozwolę im zabić mnie i moich towarzyszy, zanim nie przeleję choć trochę ich krwi.', 0),
(121, 'koKR', 'Ajeck i sir Erlgadin przygotowali broń i stanęli po obu moich bokach, plecami do morza. Barnil westchnął z rezygnacją i dobył topora. Biczoogony były już niemal przy nas. Ich miarowy krok zwolnił. Teraz podchodziły swoją ofiarę, bo wiedziały, że jesteśmy w pułapce.', 0),
(185, 'koKR', 'Wszystko zaczęło się od znalezienia tej przeklętej kosy w Zgubie Rolanda. Przed Kosą tutejsze okropności wydawały się równie niegroźne jak Dolina Północnych Włości.\n\nAle odkąd znalazłem drzewce Kosy sterczące z kupy gruzu w kopalni i – przeklęty niech będę – wyciągnąłem je, Zguba Rolanda stała się miejscem plugawej śmierci!', 0),
(205, 'koKR', 'Gdy Kosa została uwolniona, Oni rzucili się na nas zewsząd – wypełzali z ukrytych nor pod naszymi stopami i spadali na nas z cichych kryjówek w górze. Połowa naszych ludzi padła w tych pierwszych minutach paniki. Reszta, ja również, próbowała uciekać. W biegu widziałem, jak tylu moich braci porywają kły i pazury, słyszałem tyle krzyków, które nagle się urywały albo cichły w bulgocie.', 0),
(206, 'koKR', 'Mogę się tylko domyślać, dlaczego przeżyłem tamtą noc. Zawsze byłem ostrożny, zawsze szybko uchylałem się przed ciosami i odskakiwałem od pułapek. Stąd wzięło się moje przezwisko. Może więc to właśnie ta skłonność do ostrożności mnie ocaliła...\n\nA może to Kosa, którą wyciągnąłem z gruzu. Nie mogła to być sama Kosa, bo zgubiłem ją w czasie szaleńczej ucieczki. Ale jeśli to ja sprowadziłem worgenów do Kniei Zmierzchu, może worgeni okazali mi rzadką łaskę. Przeklęci niech będą.', 0),
(207, 'koKR', 'Gdy przeżyłem ucieczkę ze Zguby Rolanda, ukryłem się w stodole należącej do człowieka imieniem Sven. Spędziłem w niej kilka dni, a groza tak mnie nie opuszczała, że ani razu nie pokazałem się Svenowi ani jego rodzinie. Ale z tego, co widziałem ze swojej kryjówki, wiedziałem, że to całkiem porządni ludzie. Gdybym wyszedł z ukrycia, pewnie by mnie przygarnęli, ale trudno mi komuś zaufać. A jeszcze trudniej po tamtym wstrząsie w kopalni.\n\nZostałem więc w ukryciu.', 0),
(208, 'koKR', '<Reszta książki jest pusta>', 0),
(235, 'koKR', 'Witaj, Ello Ebonlocke, burmistrzu Mrocznych Włości. Obawiam się, że mam wieści dla twojego miasta. Grobowe wieści.$B$BWidzisz, jestem twórcą. Oszukałem okaziciela tego liściku, by pomógł mi przy moim najnowszym, najstraszliwszym dziele – potworze z ciała, kości i powykręcanego metalu! Gdy to czytasz, zapewne czeka przed moim skromnym domostwem, zgrzytając zębami, aż dam mu znak, by ruszył siać rzeź.$B$BAle wkrótce sam się przekonasz.$B$B– Balsamista', 0),
(731, 'koKR', '<HTML>\n<BODY>\n<BR/>\n<BR/>\n<H1 align="center">\nEliza\n</H1>\n<BR/>\n<BR/>\n<BR/>\n<BR/>\n<P align="center">\nUkochana żono, niech ziemia nasyci twój głód.\n</P>\n</BODY>\n</HTML>\n', 0),
(1942, 'koKR', 'W czasach, gdy w Azeroth przyszedł na świat Medivh, Kil\'jaeden Zwodziciel siedział pogrążony w posępnych rozmyślaniach pośród swych wyznawców w Wypaczonej Otchłani. Przebiegły władca demonów na rozkaz swego pana, Sargerasa, planował drugą inwazję Płonącego Legionu na Azeroth. ', 0),
(1943, 'koKR', 'Tym razem nie zamierzał dopuścić do żadnych błędów. Kil\'jaeden uznał, że potrzebuje nowej siły, która osłabi obronę Azeroth, zanim Legion w ogóle postawi stopę na tym świecie. Gdyby śmiertelne rasy, takie jak nocne elfy i smoki, musiały zmierzyć się z nowym zagrożeniem, byłyby zbyt słabe, by stawić prawdziwy opór, gdy nadejdzie właściwa inwazja Legionu.', 0),
(1944, 'koKR', 'To właśnie wtedy Kil\'jaeden odkrył bujny świat Draenor, dryfujący spokojnie w bezmiarze Wielkiej Ciemności. Draenor, dom szamańskich, żyjących w klanach orków i pokojowych draenei, był równie sielski, co rozległy. ', 0),
(1945, 'koKR', 'Szlachetne klany orków przemierzały otwarte prerie i polowały dla sportu, a dociekliwi draenei wznosili prymitywne miasta wśród strzelistych klifów i szczytów tego świata. Kil\'jaeden wiedział, że mieszkańcy Draenoru mogliby stać się cennymi sługami Płonącego Legionu, gdyby tylko odpowiednio ich ukształtować. ', 0),
(1946, 'koKR', 'Kil\'jaeden dostrzegł, że z tych dwóch ras to wojowniczy orkowie są bardziej podatni na zepsucie Legionu. Omamił starego orkowego szamana Ner\'zhula, podobnie jak przed wiekami Sargeras podporządkował sobie królową Aszarę. Posługując się przebiegłym szamanem jak narzędziem, demon szerzył wśród klanów orków żądzę walki i dzikość. ', 0),
(1947, 'koKR', 'Wkrótce ta uduchowiona rasa przemieniła się w lud żądny krwi. Kil\'jaeden nakłaniał wtedy Ner\'zhula i jego lud do ostatniego kroku: do całkowitego oddania się śmierci i wojnie. Jednak stary szaman, przeczuwając, że jego lud na zawsze stanie się niewolnikiem nienawiści, zdołał jakoś oprzeć się rozkazowi demona. ', 0),
(1948, 'koKR', 'Rozgniewany oporem Ner\'zhula Kil\'jaeden zaczął szukać innego orka, który wydałby swój lud w ręce Legionu. Przebiegły władca demonów znalazł w końcu chętnego wyznawcę, którego szukał – ambitnego ucznia Ner\'zhula, Gul\'dana. Kil\'jaeden obiecał Gul\'danowi niewyobrażalną moc w zamian za bezwzględne posłuszeństwo. ', 0),
(1949, 'koKR', 'Młody ork stał się gorliwym adeptem magii demonów i wyrósł na najpotężniejszego śmiertelnego czarnoksiężnika w dziejach. Uczył innych młodych orków tajemnych sztuk i dążył do wykorzenienia szamańskich tradycji orków. Gul\'dan ukazał swoim pobratymcom nową odmianę magii, straszliwą nową moc, od której biła woń zagłady.', 0),
(1950, 'koKR', 'Kil\'jaeden, chcąc zacieśnić swój uścisk na orkach, pomógł Gul\'danowi założyć Radę Cieni, tajną sektę, która manipulowała klanami i szerzyła użycie magii czarnoksięskiej po całym Draenorze. Im więcej orków sięgało po magię czarnoksięską, tym bardziej łagodne pola i strumienie Draenoru czerniały i marniały. Z czasem rozległe prerie, które orkowie od pokoleń nazywali domem, uschły, pozostawiając jedynie czerwoną, jałową ziemię. Demoniczne energie powoli zabijały ten świat.', 0),
(2002, 'koKR', 'Ner\'zhul i jego wyznawcy weszli do Wypaczonej Otchłani, eterycznego wymiaru, który łączy wszystkie światy rozsiane w bezmiarze Wielkiej Ciemności. Niestety, Kil\'jaeden i jego demoniczni słudzy już na nich czekali. Kil\'jaeden, który poprzysiągł zemstę na Ner\'zhulu za jego pyszne nieposłuszeństwo, powoli rozrywał ciało starego szamana na strzępy, kawałek po kawałku. ', 0),
(2003, 'koKR', 'Kil\'jaeden utrzymał ducha szamana przy życiu w nienaruszonym stanie, przez co Ner\'zhul boleśnie odczuwał okrutne rozczłonkowanie swego ciała. Choć Ner\'zhul błagał demona, by uwolnił jego ducha i dał mu śmierć, demon ponuro odparł, że Pakt krwi, który niegdyś zawarli, wciąż obowiązuje, a Ner\'zhul ma jeszcze cel do spełnienia.', 0),
(2004, 'koKR', 'Porażka orków w podboju świata dla Płonącego Legionu zmusiła Kil\'jaedena do stworzenia nowej armii, która siałaby chaos w królestwach Azeroth. Tej nowej armii nie wolno było paść ofiarą tych samych małostkowych rywalizacji i wewnętrznych waśni, które nękały Hordę. Musiała być bezlitosna i całkowicie oddana swej misji. Tym razem Kil\'jaeden nie mógł sobie pozwolić na porażkę. ', 0),
(2005, 'koKR', 'Trzymając bezbronnego ducha Ner\'zhula w zawieszeniu, Kil\'jaeden dał mu ostatnią szansę: służyć Legionowi albo cierpieć wieczne męki. Ner\'zhul po raz kolejny lekkomyślnie przystał na pakt z demonem. Ducha Ner\'zhula umieszczono w specjalnie wykutej bryle twardego jak diament lodu, zebranego z najdalszych zakątków Wypaczonej Otchłani. ', 0),
(2006, 'koKR', 'Zamknięty w lodowej skorupie Ner\'zhul poczuł, jak jego świadomość rozszerza się dziesięć tysięcy razy. Wypaczony chaotycznymi mocami demona, Ner\'zhul stał się widmową istotą o niezgłębionej potędze. W tamtej chwili ork znany jako Ner\'zhul został na zawsze roztrzaskany, a narodził się Król Lisz.', 0),
(2007, 'koKR', 'Wierni rycerze śmierci Ner\'zhula i jego wyznawcy z klanu Cienistego Księżyca również zostali przemienieni przez chaotyczne energie demona. Nikczemnych czarowników rozerwano na strzępy i przetworzono w szkieletowe lisze. Demony zadbały o to, by nawet po śmierci wyznawcy Ner\'zhula służyli mu bez szemrania.', 0),
(2008, 'koKR', 'Gdy nadszedł właściwy czas, Kil\'jaeden wyjawił misję, dla której stworzył Króla Lisza. Ner\'zhul miał rozsiać po Azeroth zarazę śmierci i grozy, która na zawsze zdusi ludzką cywilizację. Wszyscy, którzy umrą od straszliwej zarazy, powstaną jako nieumarli, a ich dusze na zawsze zostaną spętane żelazną wolą Ner\'zhula.', 0),
(2009, 'koKR', ' Kil\'jaeden obiecał, że jeśli Ner\'zhul wypełni swą mroczną misję wytępienia ludzkości ze świata, zostanie uwolniony od klątwy i otrzyma nowe, zdrowe ciało.', 0),
(2010, 'koKR', 'Choć Ner\'zhul był uległy i zdawał się gorliwie pragnąć odegrać swoją rolę, Kil\'jaeden wciąż wątpił w lojalność swego pionka. Utrzymywanie Króla Lisza bez ciała, uwięzionego w kryształowej skorupie, zapewniało jego posłuszeństwo na krótką metę, ale demon wiedział, że będzie musiał bacznie go pilnować. W tym celu Kil\'jaeden wezwał swoją elitarną straż demonów – wampirycznych upiornych władców – by nadzorowali Ner\'zhula i dopilnowali, żeby wypełnił swe straszliwe zadanie. ', 0),
(2011, 'koKR', 'Tichondrius, najpotężniejszy i najprzebieglejszy z upiornych władców, chętnie podjął się tego wyzwania; fascynowała go zjadliwość zarazy i nieokiełznany potencjał Króla Lisza do ludobójstwa.', 0);
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES
(50029, 'koKR', 'Spocznij, $N. Jeśli tylko tędy przejeżdżasz, radzę trzymać się dróg i podróżować wyłącznie za dnia. Jeśli zaś masz sprawy tu, w Mrocznych Włościach, zastanów się, czy nie oddać swoich sił na służbę Nocnej Straży. Naszych umiejętności nikt nie kwestionuje, ale jest nas niewielu.', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(61, 'koKR', '', 'Trzymaj się dróg. Las roi się od nieumarłych.', 0),
(62, 'koKR', '', 'Nie lękaj się. Nocna Straż wkrótce oczyści tę ziemię z plugawej skazy.', 0),
(68, 'koKR', 'Rada Kniei Zmierzchu musi działać. W powietrzu czai się zło.', '', 0),
(69, 'koKR', 'Mieszkańcy Mrocznych Włości oczekują od Rady więcej. Nie możemy pozwolić, by cierpieli od tego bezbożnego gniewu, który nas nęka.', '', 0),
(70, 'koKR', 'Ciągłe swary do niczego nas nie zaprowadzą. Musimy działać.', '', 0),
(71, 'koKR', 'Wieści z Wichrogrodu nie wróżą nic dobrego. . . .', '', 0),
(72, 'koKR', 'Za grubymi, kamiennymi murami Wichrogrodu nikt nie chce słuchać o naszej sprawie.', '', 0),
(73, 'koKR', '', 'Czuję, że zbiera się zło. . . .', 0),
(74, 'koKR', '', 'Gwiazdy do mnie mówią. Szepczą o okropieństwach, które czekają w mroku nocy.', 0),
(75, 'koKR', '', 'Przyszłość niesie wiele śmierci i niepewności, nie inaczej niż przeszłość.', 0),
(76, 'koKR', '', 'Duchy szepczą mi do ucha. Są niespokojne i pełne trwogi.', 0),
(77, 'koKR', 'Dziś w nocy gwiazdy ułożą się doskonale!', '', 0),
(79, 'koKR', 'Na nocnym niebie działa coś potężniejszego niż magia. Pewnego dnia mnie wysłuchają. . . .', '', 0),
(80, 'koKR', 'Pssst. Właśnie przyszła dostawa bimbru. . . .', '', 0),
(81, 'koKR', 'Podejdź bliżej i zwilż gardło.', '', 0),
(83, 'koKR', 'Witaj w „Szkarłatnym Kruku”. W dzisiejszych czasach lepiej nie wychodzić z domu.', '', 0),
(89, 'koKR', 'Powstańcie i do broni, mieszkańcy Mrocznych Włości! Drogą nadciąga plugastwo nieumarłych!', '', 0),
(90, 'koKR', 'Plugastwo rozgromiło obóz Nocnej Straży! Szybko, musimy je przechwycić, zanim dotrze do miasta!', '', 0),
(91, 'koKR', 'To za mało! Obrońcy, zbierzcie się w środku miasta. Razem stawimy czoła nieumarłej bestii!', '', 0),
(92, 'koKR', 'Plugastwo nadeszło! Naprzód!', '', 0),
(93, 'koKR', 'Bestia padła! W Mrocznych Włościach wszystko w porządku!', '', 0),
(107, 'koKR', '', 'Trzeba czegoś więcej niż gnijącego truchła, żeby nas powstrzymać!', 0),
(273, 'koKR', '', 'To nie wróży nic dobrego. Wyślijcie zwiadowców po więcej wieści i bądźcie w pogotowiu.', 0),
(507, 'koKR', 'Tilloa, to ty? Ależ skąd! To tylko jakiś plugawy brudas, $r!', '', 0),
(508, 'koKR', 'Kto śmie mnie niepokoić? Giń, $n!', '', 0),
(509, 'koKR', 'Przeleję twoją krew, $N!', '', 0),
(563, 'koKR', '%s zaczyna tłumaczyć...', '', 0),
(564, 'koKR', '$n, tłumaczenie gotowe!', '', 0),
(961, 'koKR', 'Kiedy wreszcie ktoś zrobi coś z nieumarłymi?', '', 0),
(962, 'koKR', 'Gdzie są wszyscy?', '', 0),
(963, 'koKR', 'Nie mogę już nawet w spokoju odwiedzić grobu ojca.', '', 0),
(964, 'koKR', 'Czemu straże z Wichrogrodu jeszcze nie przybyły?', '', 0),
(965, 'koKR', 'Boję się, że nadciąga coś mrocznego.', '', 0),
(966, 'koKR', 'Zdaje się, że Światłość nas opuściła.', '', 0),
(1848, 'koKR', 'Przygotowanie serum zajmie tylko kilka minut, $n.', '', 0),
(1849, 'koKR', 'Prawie gotowe...', '', 0),
(1850, 'koKR', 'Wreszcie serum jest gotowe, $n. A teraz podejdź bliżej. Musimy porozmawiać.', '', 0),
(1857, 'koKR', '%s pociąga potężny łyk piwa.', '', 0),
(1858, 'koKR', 'Ale orzeźwiające. A teraz pewne informacje muszą ujrzeć światło dzienne...', '', 0),
(1859, 'koKR', 'Sądzę, że Porzuceni wprowadzają w błąd sojuszników Hordy... zaraz... tak mi się... kręci w głowie...', '', 0),
(1860, 'koKR', '%s wije się z bólu.', '', 0),
(1861, 'koKR', 'AAAAAAAAAAAAAAAARGH!', '', 0),
(5789, 'koKR', '', 'Nie wyskakuj tak z cienia. Następnym razem uprzedź dziewczynę.', 0),
(5790, 'koKR', '', 'Odkąd cienie opanowały Knieję Zmierzchu, nie mogę spać. Nie pozwalają mi zasnąć upiorne krzyki niesione wiatrem. Brzmią niemal jak krzyk jagniąt i nie chcą ucichnąć.', 0),
(6410, 'koKR', '', '$gWidziałeś:Widziałaś; wartownika Backusa? Taki odważny...$B$BMyślę, że to najtwardszy z całej Nocnej Straży. Ciekawe, czy on w ogóle zauważa, że istnieję....', 0),
(7826, 'koKR', 'Nigdy nie jestem zbyt zajęty, żeby porozmawiać z nieznajomym! No, prawie nigdy...', '', 0),
(10886, 'koKR', 'Pokój to tylko ulotny sen! Niech zapanuje KOSZMAR!', '', 0),
(10887, 'koKR', 'Dzieci Szaleństwa – uwalniam was na ten świat!', '', 0);
